<span class="line"><span style="color:#C678DD;">    static</span><span style="color:#C678DD;"> void</span><span style="color:#61AFEF;"> CountingSortSimple</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">int</span><span style="color:#ABB2BF;">[] </span><span style="color:#E5C07B;">arr</span><span style="color:#ABB2BF;">)</span></span>
